{
  "findings": [
    {
      "check_id": "CKV_AWS_2",
      "title": "HTTP listener does not redirect to HTTPS",
      "resource": "aws_lb_listener.webserver_listner",
      "severity": "MEDIUM",
      "explanation": "The listener forwards plaintext HTTP traffic directly to the target group, allowing data in transit to remain unencrypted. Redirecting requests to HTTPS enforces use of the encrypted endpoint."
    }
  ],
  "patched_code": "resource "aws_lb_listener" "webserver_listner" {
  load_balancer_arn = aws_lb.levelup-load-balancer.arn
  port              = "80"
  protocol          = "HTTP"

  default_action {
    type = "redirect"

    redirect {
      port        = "443"
      protocol    = "HTTPS"
      status_code = "HTTP_301"
    }
  }
}
",
  "fix_summary": "Replaced direct HTTP forwarding with a permanent redirect to HTTPS on port 443, preventing the listener from serving application traffic over plaintext HTTP."
}
